const task = $input.first().json.task;
if (!task) return [];
if (typeof task.id !== 'string' || task.kind !== 'draft' || typeof task.token !== 'string') {
  throw new Error('Worker menerima tugas yang tidak cocok dengan uji ini.');
}
const divisions = {
  management:'Manajemen', operations:'IT & Operasional', administration:'Administrasi',
  hr:'SDM', development:'Pengembangan', creative:'Kreatif & Desain',
  video:'Produksi Video', social:'Media Sosial', research:'Riset & Intelijen',
  marketing:'SEO & Pemasaran', qa:'Jaminan Mutu', finance:'Keuangan'
};
const division = divisions[task.division] || 'Tim kantor';
const project = typeof task.project === 'string' && task.project.trim()
  ? task.project.trim().slice(0, 120) : 'Tidak disebutkan';
const instructions = [
  'Anda adalah asisten Anshel Virtual Tech, divisi ' + division + ', proyek ' + project + '.',
  'Buat draf Bahasa Indonesia yang menjawab instruksi pengguna secara langsung, siap ditinjau.',
  'Jika instruksi umum tidak menjelaskan topik, gunakan konteks divisi: misalnya Keuangan membahas anggaran, bukan otomatis mengubahnya menjadi agenda pemasaran.',
  'Ikuti jumlah poin yang diminta persis; jika tiga poin, buat tiga agenda utama.',
  'Jangan mengarang tanggal, lokasi, peserta, angka, sumber, atau laporan yang sudah dikirim sebagai fakta. Jika tidak diberikan, tulis Belum ditentukan bila memang perlu.',
  'Jika contoh bersifat fiktif, nyatakan sebagai contoh, bukan kejadian yang benar-benar terjadi.',
  'Jangan mengaku telah menelusuri internet, mengakses repositori, mengirim email, atau melakukan perubahan nyata.',
  'Jika instruksi dan konteks divisi bertentangan, prioritaskan instruksi eksplisit pengguna.'
].join('\n');
return [{ json: {
  id: task.id,
  token: task.token,
  request: {
    systemInstruction: { parts: [{ text: instructions }] },
    contents: [{ role: 'user', parts: [{ text: task.description }] }],
    generationConfig: { maxOutputTokens: 1200 }
  }
} }];

const { id, token } = $('Siapkan draf').first().json;
const response = $input.first().json;
const status = Number(response.statusCode);
const finish = (error, unavailable = false) => [{ json: { id, token, error, unavailable } }];
if (!status || status < 200 || status >= 300) {
  const temporary = !status || [401, 403, 404, 408, 429].includes(status) || status >= 500;
  if (!status) return finish('Gemini tidak dapat dihubungi atau melewati batas waktu.', true);
  if (status === 429) return finish('Kuota Gemini sedang terbatas. Coba lagi setelah kuota tersedia.', true);
  return finish('Gemini menolak permintaan (HTTP ' + status + ').', temporary);
}
const candidate = response.body?.candidates?.[0];
const parts = candidate?.content?.parts;
const output = Array.isArray(parts) ? parts
  .filter(part => part?.thought !== true && typeof part?.text === 'string')
  .map(part => part.text).join('').trim() : '';
if (candidate?.finishReason === 'MAX_TOKENS') return finish('Draf Gemini terpotong oleh batas keluaran.');
if (candidate?.finishReason !== 'STOP' || !output || output.length > 99000) {
  return finish('Gemini tidak mengembalikan draf lengkap yang dapat disimpan.');
}
return [{ json: { id, token, output } }];
